INSERT INTO public.user_roles(user_id,role) VALUES('00000000-0000-0000-0000-000000000065','admin');INSERT INTO public.user_account_status(user_id,account_status,disabled_at) VALUES('00000000-0000-0000-0000-000000000065','active',NULL),('00000000-0000-0000-0000-000000000066','active',NULL);
INSERT INTO public.restaurants(id,status,origin_name,naver_name,approved_name,lat,lng,geocoding_success,jibun_address,categories,tzuyang_review,trace_id,youtube_link,evaluation_results,source_type,created_by,updated_by_admin_id,phone) SELECT id,status,origin_name,naver_name,approved_name,lat,lng,geocoding_success,jibun_address,categories,tzuyang_review,trace_id,youtube_link,evaluation_results,source_type,created_by,updated_by_admin_id,phone FROM jsonb_populate_record(NULL::public.restaurants,'{"id": "de0a3945-3b00-4f98-974c-1e505ef52b0f", "status": "pending", "origin_name": "fixture branch", "naver_name": "fixture branch", "approved_name": "fixture branch", "lat": 37.5, "lng": 127, "geocoding_success": true, "jibun_address": "synthetic business address", "categories": ["\ud55c\uc2dd"], "tzuyang_review": "fixture review", "trace_id": "fd7bb6314e554d2e972dc13cf454ebcc", "youtube_link": "https://www.youtube.com/watch?v=ABCDEFGHIJK", "evaluation_results": {"visit_authenticity": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_inference_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "review_faithfulness_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_grounding_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_validity_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "location_match_TF": {"origin_name": "fixture branch", "eval_value": true, "match_status": "matched", "evidence_families": ["source_geo", "provider_candidate"]}}, "source_type": "crawler", "created_by": null, "updated_by_admin_id": null, "phone": "02-777-0000"}'::jsonb);INSERT INTO pipeline_control.restaurant_review_policy(singleton,version,enabled,operator_id,batch_size,daily_limit) VALUES(true,7,true,'00000000-0000-0000-0000-000000000065',1,50);INSERT INTO pipeline_control.restaurant_review_runs(id,request_id,policy_version) VALUES('00000000-0000-4000-8000-000000000301',gen_random_uuid(),7);INSERT INTO pipeline_control.restaurant_review_items(run_id,restaurant_id,fingerprint,applied_fingerprint,decision,reason,state) SELECT '00000000-0000-4000-8000-000000000301',id,repeat('b',64),pipeline_control.restaurant_review_fingerprint(to_jsonb(t)),'recheck','fixture','applied' FROM public.restaurants t WHERE id='de0a3945-3b00-4f98-974c-1e505ef52b0f';SET LOCAL ROLE service_role;SELECT set_config('request.jwt.claim.role','',true);SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);DO $test$ DECLARE a jsonb;BEGIN a:=public.restaurant_review_automation_tick(gen_random_uuid());IF (a->>'scanned')::int<>0 OR (SELECT count(*) FROM pipeline_control.restaurant_review_items)<>1 OR (SELECT status FROM public.restaurants WHERE id='de0a3945-3b00-4f98-974c-1e505ef52b0f')<>'pending' THEN RAISE EXCEPTION 'REVIEW_FIX_FP_EXCLUSION';END IF;END $test$;ROLLBACK;